window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bf20e9aa2cbf8ad3"]={"versions": [{"id": "FIG-bf20e9aa2cbf8ad3", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Adaptive Platform Manifests / ARXML-Metamodell).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R20-11, Dokumentation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel 12 (<em>Interaction between Functional Clusters</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Modellierung und Entkopplung von hersteller- und clusterspezifischen Querverbindungen sowie Ressourcen-Abhängigkeiten zwischen standardisierten Functional Clustern (FCs) der Adaptive Platform Foundation/Services. Anstelle proprietärer IPC-Mechanismen oder hardkodierter Pfade ermöglicht die Spezialisierungshierarchie die deklarative Zuordnung von kryptografischen Schlüsselslots, Zertifikaten, Persistenzbereichen, Zeitbasen und Diagnose-Log-Kanälen im Machine- bzw. Platform-Manifest.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Abstrakte Basisebene</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadablePackageElement</code>:</strong></li>\n<li>Abstrakte Metaklasse des ARXML-Metamodells (spezialisiert von <code>ARElement</code>), die festlegt, dass Instanzen als eigenständige Deployment-Artefakte bzw. Software-Packages über Update and Configuration Management (UCM) auf das Zielsystem ausgerollt werden können.</li>\n<li><strong><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> (kursiv/abstrakt):</strong></li>\n<li>Generalisierung aller Interaktions-Mappings zwischen zwei oder mehr Functional Clustern. Spezialisiert <code>UploadablePackageElement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierte Subklassen (Konkrete Mapping-Entitäten)</p>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt ein globales Persistenz-Deployment (<code>PersistencyDeployment</code>, z. B. <code>PersistencyFileStorage</code> oder <code>PersistencyKeyValueStorage</code>) auf einen kryptografischen Schlüsselslot (<code>CryptoKeySlot</code>).</li>\n<li>Attribute:</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code>: Spezifiziert den Einsatzzweck des Schlüsselslots innerhalb der Persistenz (z. B. Verschlüsselung von Datenblöcken oder Integritätssicherung).</li>\n<li><code>+ verificationHash: String [0..1]</code>: Optionaler kryptografischer Hashwert zur Integritäts- und Konsistenzprüfung des referenzierten Schlüsselinhalts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Zuordnung auf Elementebene: Mappt einzelne Dateien oder einzelne Key-Value-Einträge (<code>PersistencyDeploymentElement</code>) auf dedizierte <code>CryptoKeySlot</code>-Instanzen.</li>\n<li>Attribute:</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code></li>\n<li><code>+ verificationHash: String [0..1]</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComCertificateToCryptoCertificateMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindet Kommunikationsendpunkte des Communication Management (<code>ara::com</code>, z. B. TLS-Verbindungen bei SOME/IP oder DDS) an im Cryptography Cluster (<code>ara::crypto</code>) verwaltete X.509-Zertifikate (<code>CryptoCertificate</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComKeyToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ordnet Kommunikationsprotokoll-Sicherheitsschlüssel (z. B. Pre-Shared Keys) konkreten <code>CryptoKeySlot</code>-Ressourcen zu.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComSecOcToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verbindet die PDU-Authentifizierung und Freshness-Prüfung von Secure Onboard Communication (<code>SecOC</code>) mit den kryptografischen Schlüsselslots zur MAC-Generierung und -Verifikation.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>TimeBaseProviderToPersistencyMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt den Zeitbasen-Provider des Time Synchronization Clusters (<code>TimeBaseProvider</code> / <code>ara::tsync</code>) auf eine Persistenz-Ressource (<code>ara::per</code>), um Zeitkorrekturwerte, Offset-Werte und Drift-Zustände über Reboot- und Power-Down-Zyklen hinweg zu konservieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToDltLogChannelMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weist einem <code>PersistencyDeployment</code> dedizierte Log-Kanäle (<code>DltLogChannel</code>) des Diagnostic Log and Trace Clusters (<code>ara::dlt</code>) zu, um Persistenz-Events, I/O-Fehler und Migrationsmeldungen strukturiert zu loggen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert eine rein statische Metamodell-Struktur für Build- und Packaging-Artefakte (Manifeste). Die zur Laufzeit abgeleitete Dynamik gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Manifest-Evaluation & Deployment (UCM / Execution Management):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beim Parsen des Manifest-Pakets liest der Plattform-Bootstrapper die Subklassen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> ein.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inter-Cluster-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Persistency & Crypto:</em> <code>ara::per</code> fragt beim Start über den Crypto-Provider den im Mapping definierten <code>CryptoKeySlot</code> ab. Stimmen <code>keySlotUsage</code> oder <code>verificationHash</code> nicht mit den Crypto-Manifest-Definitionen überein, schlägt die Initialisierung der Storage-Instanz fehl.</li>\n<li><em>Communication & SecOC / Crypto:</em> Der Netzwerk-Stack verifiziert vor dem Senden/Empfangen gesicherter PDUs die Verfügbarkeit der zugeordneten Slots und Zertifikate.</li>\n<li><em>TimeSync & Persistency:</em> <code>ara::tsync</code> liest synchron gespeicherte Zeitversatzdaten aus dem gemappten Persistenzspeicher ein, bevor die Zeitbasis als synchronisiert (<code>kSynchronized</code>) an Clients gemeldet wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerpfade:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ungültige oder unauflösbare Referenzen führen zu Plattform-Initialisierungsfehlern, die über das Platform Health Management (PHM) erfasst oder via DLT als kritischer Fehler geloggt werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>TPS_MANI_03268</code>):</strong></li>\n<li>Schreibt vor, dass sämtliche plattforminternen Cluster-Interaktionen und Querverweise explizit über die Spezialisierungen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> deklariert werden müssen. Versteckte, herstellerspezifische Abhängigkeiten zwischen funktionalen Clustern verletzen die Konformität.</li>\n<li><strong>Konfigurations- & Integrator-Pflichten:</strong></li>\n<li><em>Ressourcen-Isolation:</em> Integratoren müssen für jedes Persistenz- und Kommunikations-Deployment eindeutige Key-Slot- und Kanal-Mappings definieren. Schlüsselkollisionen werden durch <code>verificationHash</code> frühzeitig zur Konfigurations-Validierungszeit abgefangen.</li>\n<li><em>Granularität:</em> Entwickler müssen zwischen Storage-weiter Verschlüsselung (<code>PersistencyDeploymentToCryptoKeySlotMapping</code>) und datei-/schlüsselspezifischer Verschlüsselung (<code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>) differenzieren, um Overheads im Crypto-Hardwaretreiber (z. B. HSM/SE) zu minimieren.</li>\n<li><strong>Implementierungs-Vertrag für Stack-Anbieter:</strong></li>\n<li>Codegeneratoren für <code>ara::per</code>, <code>ara::com</code> und <code>ara::tsync</code> müssen diese Mappings auswerten, um die entsprechenden Driver-Handles, IPC-Endpunkte und Proxy/Skeleton-Instanzen konsistent aufeinander abzustimmen.</li>\n<li>Applikations-SWCs interagieren ausschließlich mit den abstrakten Standard-APIs (z. B. <code>ara::per::OpenFileStorage</code>); das Routing zu HSM-Slots oder DLT-Kanälen erfolgt für die Anwendung vollkommen transparent auf Basis dieser Mappings.</li>\n</ul>"}, {"id": "FIG-d3953a207d128541", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Adaptive Platform Manifests / ARXML-Metamodell).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R20-11, Dokumentation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel 12 (<em>Interaction between Functional Clusters</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Modellierung und Entkopplung von hersteller- und clusterspezifischen Querverbindungen sowie Ressourcen-Abhängigkeiten zwischen standardisierten Functional Clustern (FCs) der Adaptive Platform Foundation/Services. Anstelle proprietärer IPC-Mechanismen oder hardkodierter Pfade ermöglicht die Spezialisierungshierarchie die deklarative Zuordnung von kryptografischen Schlüsselslots, Zertifikaten, Persistenzbereichen, Zeitbasen und Diagnose-Log-Kanälen im Machine- bzw. Platform-Manifest.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Abstrakte Basisebene</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadablePackageElement</code>:</strong></li>\n<li>Abstrakte Metaklasse des ARXML-Metamodells (spezialisiert von <code>ARElement</code>), die festlegt, dass Instanzen als eigenständige Deployment-Artefakte bzw. Software-Packages über Update and Configuration Management (UCM) auf das Zielsystem ausgerollt werden können.</li>\n<li><strong><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> (kursiv/abstrakt):</strong></li>\n<li>Generalisierung aller Interaktions-Mappings zwischen zwei oder mehr Functional Clustern. Spezialisiert <code>UploadablePackageElement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierte Subklassen (Konkrete Mapping-Entitäten)</p>\n<ol class=\"fig-list\">\n<li><strong><code>ArtifactChecksumToCryptoProviderMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt Prüfsummen von Software-Artefakten auf kryptografische Provider (<code>CryptoProvider</code>), um kryptografische Integritäts- und Authentizitätsprüfungen von Artefakten durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt ein globales Persistenz-Deployment (<code>PersistencyDeployment</code>, z. B. <code>PersistencyFileStorage</code> oder <code>PersistencyKeyValueStorage</code>) auf einen kryptografischen Schlüsselslot (<code>CryptoKeySlot</code>).</li>\n<li>Attribute:</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code>: Spezifiziert den Einsatzzweck des Schlüsselslots innerhalb der Persistenz (z. B. Verschlüsselung von Datenblöcken oder Integritätssicherung).</li>\n<li><code>+ verificationHash: String [0..1]</code>: Optionaler kryptografischer Hashwert zur Integritäts- und Konsistenzprüfung des referenzierten Schlüsselinhalts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Zuordnung auf Elementebene: Mappt einzelne Dateien oder einzelne Key-Value-Einträge (<code>PersistencyDeploymentElement</code>) auf dedizierte <code>CryptoKeySlot</code>-Instanzen.</li>\n<li>Attribute:</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code></li>\n<li><code>+ verificationHash: String [0..1]</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToDltLogSinkMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weist einem <code>PersistencyDeployment</code> dedizierte Log-Senken (<code>DltLogSink</code>) des Diagnostic Log and Trace Clusters (<code>ara::dlt</code>) zu, um Persistenz-Events, I/O-Fehler und Protokollmeldungen an konfigurierte Protokollsenken weiterzuleiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>TimeBaseProviderToPersistencyMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt den Zeitbasen-Provider des Time Synchronization Clusters (<code>TimeBaseProvider</code> / <code>ara::tsync</code>) auf eine Persistenz-Ressource (<code>ara::per</code>), um Zeitkorrekturwerte, Offset-Werte und Drift-Zustände über Reboot- und Power-Down-Zyklen hinweg zu konservieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComSecOcToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verbindet die PDU-Authentifizierung und Freshness-Prüfung von Secure Onboard Communication (<code>SecOC</code>) mit den kryptografischen Schlüsselslots zur MAC-Generierung und -Verifikation.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComKeyToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ordnet Kommunikationsprotokoll-Sicherheitsschlüssel (z. B. Pre-Shared Keys) konkreten <code>CryptoKeySlot</code>-Ressourcen zu.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComCertificateToCryptoCertificateMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindet Kommunikationsendpunkte des Communication Management (<code>ara::com</code>, z. B. TLS-Verbindungen bei SOME/IP oder DDS) an im Cryptography Cluster (<code>ara::crypto</code>) verwaltete X.509-Zertifikate (<code>CryptoCertificate</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert eine rein statische Metamodell-Struktur für Build- und Packaging-Artefakte (Manifeste). Die zur Laufzeit abgeleitete Dynamik gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Manifest-Evaluation & Deployment (UCM / Execution Management):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beim Parsen des Manifest-Pakets liest der Plattform-Bootstrapper die Subklassen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> ein.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inter-Cluster-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Persistency & Crypto:</em> <code>ara::per</code> fragt beim Start über den Crypto-Provider den im Mapping definierten <code>CryptoKeySlot</code> ab. Stimmen <code>keySlotUsage</code> oder <code>verificationHash</code> nicht mit den Crypto-Manifest-Definitionen überein, schlägt die Initialisierung der Storage-Instanz fehl.</li>\n<li><em>Communication & SecOC / Crypto:</em> Der Netzwerk-Stack verifiziert vor dem Senden/Empfangen gesicherter PDUs die Verfügbarkeit der zugeordneten Slots und Zertifikate.</li>\n<li><em>TimeSync & Persistency:</em> <code>ara::tsync</code> liest synchron gespeicherte Zeitversatzdaten aus dem gemappten Persistenzspeicher ein, bevor die Zeitbasis als synchronisiert (<code>kSynchronized</code>) an Clients gemeldet wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerpfade:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ungültige oder unauflösbare Referenzen führen zu Plattform-Initialisierungsfehlern, die über das Platform Health Management (PHM) erfasst oder via DLT als kritischer Fehler geloggt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>TPS_MANI_03268</code>):</strong></li>\n<li>Schreibt vor, dass sämtliche plattforminternen Cluster-Interaktionen und Querverweise explizit über die Spezialisierungen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> deklariert werden müssen. Versteckte, herstellerspezifische Abhängigkeiten zwischen funktionalen Clustern verletzen die Konformität.</li>\n<li><strong>Konfigurations- & Integrator-Pflichten:</strong></li>\n<li><em>Ressourcen-Isolation:</em> Integratoren müssen für jedes Persistenz- und Kommunikations-Deployment eindeutige Key-Slot- und Kanal-Mappings definieren. Schlüsselkollisionen werden durch <code>verificationHash</code> frühzeitig zur Konfigurations-Validierungszeit abgefangen.</li>\n<li><em>Granularität:</em> Entwickler müssen zwischen Storage-weiter Verschlüsselung (<code>PersistencyDeploymentToCryptoKeySlotMapping</code>) und datei-/schlüsselspezifischer Verschlüsselung (<code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>) differenzieren, um Overheads im Crypto-Hardwaretreiber (z. B. HSM/SE) zu minimieren.</li>\n<li><strong>Implementierungs-Vertrag für Stack-Anbieter:</strong></li>\n<li>Codegeneratoren für <code>ara::per</code>, <code>ara::com</code> und <code>ara::tsync</code> müssen diese Mappings auswerten, um die entsprechenden Driver-Handles, IPC-Endpunkte und Proxy/Skeleton-Instanzen konsistent aufeinander abzustimmen.</li>\n<li>Applikations-SWCs interagieren ausschließlich mit den abstrakten Standard-APIs (z. B. <code>ara::per::OpenFileStorage</code>); das Routing zu HSM-Slots oder DLT-Kanälen erfolgt für die Anwendung vollkommen transparent auf Basis dieser Mappings.</li>\n</ul>"}, {"id": "FIG-503f067b90ed1904", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Adaptive Platform Manifests / ARXML-Metamodell).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R20-11, Dokumentation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel 12 (<em>Interaction between Functional Clusters</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Modellierung und Entkopplung von hersteller- und clusterspezifischen Querverbindungen sowie Ressourcen-Abhängigkeiten zwischen standardisierten Functional Clustern (FCs) der Adaptive Platform Foundation/Services. Anstelle proprietärer IPC-Mechanismen oder hardkodierter Pfade ermöglicht die Spezialisierungshierarchie die deklarative Zuordnung von kryptografischen Schlüsselslots, Zertifikaten, Persistenzbereichen, Zeitbasen und Diagnose-Log-Kanälen im Machine- bzw. Platform-Manifest.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Abstrakte Basisebene</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadablePackageElement</code>:</strong></li>\n<li>Abstrakte Metaklasse des ARXML-Metamodells (spezialisiert von <code>ARElement</code>), die festlegt, dass Instanzen als eigenständige Deployment-Artefakte bzw. Software-Packages über Update and Configuration Management (UCM) auf das Zielsystem ausgerollt werden können.</li>\n<li><strong><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> (kursiv/abstrakt):</strong></li>\n<li>Generalisierung aller Interaktions-Mappings zwischen zwei oder mehr Functional Clustern. Spezialisiert <code>UploadablePackageElement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierte Subklassen (Konkrete Mapping-Entitäten)</p>\n<ol class=\"fig-list\">\n<li><strong><code>ArtifactChecksumToCryptoProviderMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt Prüfsummen von Software-Artefakten auf kryptografische Provider (<code>CryptoProvider</code>), um kryptografische Integritäts- und Authentizitätsprüfungen von Artefakten durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt ein globales Persistenz-Deployment (<code>PersistencyDeployment</code>, z. B. <code>PersistencyFileStorage</code> oder <code>PersistencyKeyValueStorage</code>) auf einen kryptografischen Schlüsselslot (<code>CryptoKeySlot</code>).</li>\n<li>Attribute:</li>\n<li><code>+ cryptoAlgorithmString: String [0..1]</code>: Spezifiziert den für die Persistenzverschlüsselung zu verwendenden kryptografischen Algorithmus als String-Identifier.</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code>: Spezifiziert den Einsatzzweck des Schlüsselslots innerhalb der Persistenz (z. B. Verschlüsselung von Datenblöcken oder Integritätssicherung).</li>\n<li><code>+ verificationHash: String [0..1]</code>: Optionaler kryptografischer Hashwert zur Integritäts- und Konsistenzprüfung des referenzierten Schlüsselinhalts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Zuordnung auf Elementebene: Mappt einzelne Dateien oder einzelne Key-Value-Einträge (<code>PersistencyDeploymentElement</code>) auf dedizierte <code>CryptoKeySlot</code>-Instanzen.</li>\n<li>Attribute:</li>\n<li><code>+ cryptoAlgorithmString: String [0..1]</code>: Spezifiziert den kryptografischen Algorithmus für das spezifische Persistenz-Deployment-Element.</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code></li>\n<li><code>+ verificationHash: String [0..1]</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToDltLogSinkMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weist einem <code>PersistencyDeployment</code> dedizierte Log-Senken (<code>DltLogSink</code>) des Diagnostic Log and Trace Clusters (<code>ara::dlt</code>) zu, um Persistenz-Events, I/O-Fehler und Protokollmeldungen an konfigurierte Protokollsenken weiterzuleiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>TimeBaseProviderToPersistencyMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt den Zeitbasen-Provider des Time Synchronization Clusters (<code>TimeBaseProvider</code> / <code>ara::tsync</code>) auf eine Persistenz-Ressource (<code>ara::per</code>), um Zeitkorrekturwerte, Offset-Werte und Drift-Zustände über Reboot- und Power-Down-Zyklen hinweg zu konservieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComSecOcToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verbindet die PDU-Authentifizierung und Freshness-Prüfung von Secure Onboard Communication (<code>SecOC</code>) mit den kryptografischen Schlüsselslots zur MAC-Generierung und -Verifikation.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComKeyToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ordnet Kommunikationsprotokoll-Sicherheitsschlüssel (z. B. Pre-Shared Keys) konkreten <code>CryptoKeySlot</code>-Ressourcen zu.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComCertificateToCryptoCertificateMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindet Kommunikationsendpunkte des Communication Management (<code>ara::com</code>, z. B. TLS-Verbindungen bei SOME/IP oder DDS) an im Cryptography Cluster (<code>ara::crypto</code>) verwaltete X.509-Zertifikate (<code>CryptoCertificate</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert eine rein statische Metamodell-Struktur für Build- und Packaging-Artefakte (Manifeste). Die zur Laufzeit abgeleitete Dynamik gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Manifest-Evaluation & Deployment (UCM / Execution Management):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beim Parsen des Manifest-Pakets liest der Plattform-Bootstrapper die Subklassen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> ein.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inter-Cluster-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Persistency & Crypto:</em> <code>ara::per</code> fragt beim Start über den Crypto-Provider den im Mapping definierten <code>CryptoKeySlot</code> ab. Stimmen <code>keySlotUsage</code> oder <code>verificationHash</code> nicht mit den Crypto-Manifest-Definitionen überein, schlägt die Initialisierung der Storage-Instanz fehl.</li>\n<li><em>Communication & SecOC / Crypto:</em> Der Netzwerk-Stack verifiziert vor dem Senden/Empfangen gesicherter PDUs die Verfügbarkeit der zugeordneten Slots und Zertifikate.</li>\n<li><em>TimeSync & Persistency:</em> <code>ara::tsync</code> liest synchron gespeicherte Zeitversatzdaten aus dem gemappten Persistenzspeicher ein, bevor die Zeitbasis als synchronisiert (<code>kSynchronized</code>) an Clients gemeldet wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerpfade:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ungültige oder unauflösbare Referenzen führen zu Plattform-Initialisierungsfehlern, die über das Platform Health Management (PHM) erfasst oder via DLT als kritischer Fehler geloggt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>TPS_MANI_03268</code>):</strong></li>\n<li>Schreibt vor, dass sämtliche plattforminternen Cluster-Interaktionen und Querverweise explizit über die Spezialisierungen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> deklariert werden müssen. Versteckte, herstellerspezifische Abhängigkeiten zwischen funktionalen Clustern verletzen die Konformität.</li>\n<li><strong>Konfigurations- & Integrator-Pflichten:</strong></li>\n<li><em>Ressourcen-Isolation:</em> Integratoren müssen für jedes Persistenz- und Kommunikations-Deployment eindeutige Key-Slot- und Kanal-Mappings definieren. Schlüsselkollisionen werden durch <code>verificationHash</code> frühzeitig zur Konfigurations-Validierungszeit abgefangen.</li>\n<li><em>Granularität:</em> Entwickler müssen zwischen Storage-weiter Verschlüsselung (<code>PersistencyDeploymentToCryptoKeySlotMapping</code>) und datei-/schlüsselspezifischer Verschlüsselung (<code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>) differenzieren, um Overheads im Crypto-Hardwaretreiber (z. B. HSM/SE) zu minimieren.</li>\n<li><strong>Implementierungs-Vertrag für Stack-Anbieter:</strong></li>\n<li>Codegeneratoren für <code>ara::per</code>, <code>ara::com</code> und <code>ara::tsync</code> müssen diese Mappings auswerten, um die entsprechenden Driver-Handles, IPC-Endpunkte und Proxy/Skeleton-Instanzen konsistent aufeinander abzustimmen.</li>\n<li>Applikations-SWCs interagieren ausschließlich mit den abstrakten Standard-APIs (z. B. <code>ara::per::OpenFileStorage</code>); das Routing zu HSM-Slots oder DLT-Kanälen erfolgt für die Anwendung vollkommen transparent auf Basis dieser Mappings.</li>\n</ul>"}, {"id": "FIG-2dc21ccbfe84f651", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Adaptive Platform Manifests / ARXML-Metamodell).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R20-11, Dokumentation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel 12 (<em>Interaction between Functional Clusters</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Modellierung und Entkopplung von hersteller- und clusterspezifischen Querverbindungen sowie Ressourcen-Abhängigkeiten zwischen standardisierten Functional Clustern (FCs) der Adaptive Platform Foundation/Services. Anstelle proprietärer IPC-Mechanismen oder hardkodierter Pfade ermöglicht die Spezialisierungshierarchie die deklarative Zuordnung von kryptografischen Schlüsselslots, Zertifikaten, Persistenzbereichen, Zeitbasen und Diagnose-Log-Kanälen im Machine- bzw. Platform-Manifest.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Abstrakte Basisebene</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadableDeploymentElement</code>:</strong></li>\n<li>Abstrakte Metaklasse des ARXML-Metamodells, die festlegt, dass Instanzen als deployment-spezifische Konfigurationselemente eigenständig über Update and Configuration Management (UCM) deployt werden können (ersetzt <code>UploadablePackageElement</code>).</li>\n<li><strong><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> (kursiv/abstrakt):</strong></li>\n<li>Generalisierung aller Interaktions-Mappings zwischen zwei oder mehr Functional Clustern. Spezialisiert <code>UploadableDeploymentElement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierte Subklassen (Konkrete Mapping-Entitäten)</p>\n<ol class=\"fig-list\">\n<li><strong><code>ArtifactChecksumToCryptoProviderMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt Prüfsummen von Software-Artefakten auf kryptografische Provider (<code>CryptoProvider</code>), um kryptografische Integritäts- und Authentizitätsprüfungen von Artefakten durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt ein globales Persistenz-Deployment (<code>PersistencyDeployment</code>, z. B. <code>PersistencyFileStorage</code> oder <code>PersistencyKeyValueStorage</code>) auf einen kryptografischen Schlüsselslot (<code>CryptoKeySlot</code>).</li>\n<li>Attribute:</li>\n<li><code>+ cryptoAlgorithmString: String [0..1]</code>: Spezifiziert den für die Persistenzverschlüsselung zu verwendenden kryptografischen Algorithmus als String-Identifier.</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code>: Spezifiziert den Einsatzzweck des Schlüsselslots innerhalb der Persistenz (z. B. Verschlüsselung von Datenblöcken oder Integritätssicherung).</li>\n<li><code>+ verificationHash: String [0..1]</code>: Optionaler kryptografischer Hashwert zur Integritäts- und Konsistenzprüfung des referenzierten Schlüsselinhalts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Zuordnung auf Elementebene: Mappt einzelne Dateien oder einzelne Key-Value-Einträge (<code>PersistencyDeploymentElement</code>) auf dedizierte <code>CryptoKeySlot</code>-Instanzen.</li>\n<li>Attribute:</li>\n<li><code>+ cryptoAlgorithmString: String [0..1]</code></li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code></li>\n<li><code>+ verificationHash: String [0..1]</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToDltLogSinkMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weist einem <code>PersistencyDeployment</code> dedizierte Log-Senken (<code>DltLogSink</code>) des Diagnostic Log and Trace Clusters (<code>ara::dlt</code>) zu, um Persistenz-Events, I/O-Fehler und Protokollmeldungen an konfigurierte Protokollsenken weiterzuleiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>TimeBaseProviderToPersistencyMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt den Zeitbasen-Provider des Time Synchronization Clusters (<code>TimeBaseProvider</code> / <code>ara::tsync</code>) auf eine Persistenz-Ressource (<code>ara::per</code>), um Zeitkorrekturwerte, Offset-Werte und Drift-Zustände über Reboot- und Power-Down-Zyklen hinweg zu konservieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComSecOcToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verbindet die PDU-Authentifizierung und Freshness-Prüfung von Secure Onboard Communication (<code>SecOC</code>) mit den kryptografischen Schlüsselslots zur MAC-Generierung und -Verifikation.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComKeyToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ordnet Kommunikationsprotokoll-Sicherheitsschlüssel (z. B. Pre-Shared Keys) konkreten <code>CryptoKeySlot</code>-Ressourcen zu.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComCertificateToCryptoCertificateMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindet Kommunikationsendpunkte des Communication Management (<code>ara::com</code>, z. B. TLS-Verbindungen bei SOME/IP oder DDS) an im Cryptography Cluster (<code>ara::crypto</code>) verwaltete X.509-Zertifikate (<code>CryptoCertificate</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FunctionalClusterToSecurityEventDefinitionMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verknüpft funktionale Cluster mit Security-Event-Definitionen (<code>SecurityEventDefinition</code>) des Intrusion Detection System Manager (IdsM), um sicherheitsrelevante Ereignisse und Anomalien standardisiert an das IdsM zu melden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert eine rein statische Metamodell-Struktur für Build- und Packaging-Artefakte (Manifeste). Die zur Laufzeit abgeleitete Dynamik gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Manifest-Evaluation & Deployment (UCM / Execution Management):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beim Parsen des Manifest-Pakets liest der Plattform-Bootstrapper die Subklassen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> ein.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inter-Cluster-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Persistency & Crypto:</em> <code>ara::per</code> fragt beim Start über den Crypto-Provider den im Mapping definierten <code>CryptoKeySlot</code> ab. Stimmen <code>keySlotUsage</code> oder <code>verificationHash</code> nicht mit den Crypto-Manifest-Definitionen überein, schlägt die Initialisierung der Storage-Instanz fehl.</li>\n<li><em>Communication & SecOC / Crypto:</em> Der Netzwerk-Stack verifiziert vor dem Senden/Empfangen gesicherter PDUs die Verfügbarkeit der zugeordneten Slots und Zertifikate.</li>\n<li><em>TimeSync & Persistency:</em> <code>ara::tsync</code> liest synchron gespeicherte Zeitversatzdaten aus dem gemappten Persistenzspeicher ein, bevor die Zeitbasis als synchronisiert (<code>kSynchronized</code>) an Clients gemeldet wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerpfade:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ungültige oder unauflösbare Referenzen führen zu Plattform-Initialisierungsfehlern, die über das Platform Health Management (PHM) erfasst oder via DLT als kritischer Fehler geloggt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>TPS_MANI_03268</code>):</strong></li>\n<li>Schreibt vor, dass sämtliche plattforminternen Cluster-Interaktionen und Querverweise explizit über die Spezialisierungen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> deklariert werden müssen. Versteckte, herstellerspezifische Abhängigkeiten zwischen funktionalen Clustern verletzen die Konformität.</li>\n<li><strong>Konfigurations- & Integrator-Pflichten:</strong></li>\n<li><em>Ressourcen-Isolation:</em> Integratoren müssen für jedes Persistenz- und Kommunikations-Deployment eindeutige Key-Slot- und Kanal-Mappings definieren. Schlüsselkollisionen werden durch <code>verificationHash</code> frühzeitig zur Konfigurations-Validierungszeit abgefangen.</li>\n<li><em>Granularität:</em> Entwickler müssen zwischen Storage-weiter Verschlüsselung (<code>PersistencyDeploymentToCryptoKeySlotMapping</code>) und datei-/schlüsselspezifischer Verschlüsselung (<code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>) differenzieren, um Overheads im Crypto-Hardwaretreiber (z. B. HSM/SE) zu minimieren.</li>\n<li><strong>Implementierungs-Vertrag für Stack-Anbieter:</strong></li>\n<li>Codegeneratoren für <code>ara::per</code>, <code>ara::com</code> und <code>ara::tsync</code> müssen diese Mappings auswerten, um die entsprechenden Driver-Handles, IPC-Endpunkte und Proxy/Skeleton-Instanzen konsistent aufeinander abzustimmen.</li>\n<li>Applikations-SWCs interagieren ausschließlich mit den abstrakten Standard-APIs (z. B. <code>ara::per::OpenFileStorage</code>); das Routing zu HSM-Slots oder DLT-Kanälen erfolgt für die Anwendung vollkommen transparent auf Basis dieser Mappings.</li>\n</ul>"}, {"id": "FIG-85181755e287e540", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Adaptive Platform Manifests / ARXML-Metamodell).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R20-11, Dokumentation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel 12 (<em>Interaction between Functional Clusters</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Modellierung und Entkopplung von hersteller- und clusterspezifischen Querverbindungen sowie Ressourcen-Abhängigkeiten zwischen standardisierten Functional Clustern (FCs) der Adaptive Platform Foundation/Services. Anstelle proprietärer IPC-Mechanismen oder hardkodierter Pfade ermöglicht die Spezialisierungshierarchie die deklarative Zuordnung von kryptografischen Schlüsselslots, Zertifikaten, Persistenzbereichen, Zeitbasen und Diagnose-Log-Kanälen im Machine- bzw. Platform-Manifest.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Abstrakte Basisebene</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadableDeploymentElement</code>:</strong></li>\n<li>Abstrakte Metaklasse des ARXML-Metamodells, die festlegt, dass Instanzen als deployment-spezifische Konfigurationselemente eigenständig über Update and Configuration Management (UCM) deployt werden können (ersetzt <code>UploadablePackageElement</code>).</li>\n<li><strong><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> (kursiv/abstrakt):</strong></li>\n<li>Generalisierung aller Interaktions-Mappings zwischen zwei oder mehr Functional Clustern. Spezialisiert <code>UploadableDeploymentElement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierte Subklassen (Konkrete Mapping-Entitäten)</p>\n<ol class=\"fig-list\">\n<li><strong><code>ArtifactChecksumToCryptoProviderMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt Prüfsummen von Software-Artefakten auf kryptografische Provider (<code>CryptoProvider</code>), um kryptografische Integritäts- und Authentizitätsprüfungen von Artefakten durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt ein globales Persistenz-Deployment (<code>PersistencyDeployment</code>, z. B. <code>PersistencyFileStorage</code> oder <code>PersistencyKeyValueStorage</code>) auf einen kryptografischen Schlüsselslot (<code>CryptoKeySlot</code>).</li>\n<li>Attribute:</li>\n<li><code>+ cryptoAlgorithmString: String [0..1]</code>: Spezifiziert den für die Persistenzverschlüsselung zu verwendenden kryptografischen Algorithmus als String-Identifier.</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code>: Spezifiziert den Einsatzzweck des Schlüsselslots innerhalb der Persistenz (z. B. Verschlüsselung von Datenblöcken oder Integritätssicherung).</li>\n<li><code>+ verificationHash: String [0..1]</code>: Optionaler kryptografischer Hashwert zur Integritäts- und Konsistenzprüfung des referenzierten Schlüsselinhalts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Zuordnung auf Elementebene: Mappt einzelne Dateien oder einzelne Key-Value-Einträge (<code>PersistencyDeploymentElement</code>) auf dedizierte <code>CryptoKeySlot</code>-Instanzen.</li>\n<li>Attribute:</li>\n<li><code>+ cryptoAlgorithmString: String [0..1]</code></li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code></li>\n<li><code>+ verificationHash: String [0..1]</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToDltLogSinkMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weist einem <code>PersistencyDeployment</code> dedizierte Log-Senken (<code>DltLogSink</code>) des Diagnostic Log and Trace Clusters (<code>ara::dlt</code>) zu, um Persistenz-Events, I/O-Fehler und Protokollmeldungen an konfigurierte Protokollsenken weiterzuleiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>TimeBaseProviderToPersistencyMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt den Zeitbasen-Provider des Time Synchronization Clusters (<code>TimeBaseProvider</code> / <code>ara::tsync</code>) auf eine Persistenz-Ressource (<code>ara::per</code>), um Zeitkorrekturwerte, Offset-Werte und Drift-Zustände über Reboot- und Power-Down-Zyklen hinweg zu konservieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComSecOcToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verbindet die PDU-Authentifizierung und Freshness-Prüfung von Secure Onboard Communication (<code>SecOC</code>) mit den kryptografischen Schlüsselslots zur MAC-Generierung und -Verifikation.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComKeyToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ordnet Kommunikationsprotokoll-Sicherheitsschlüssel (z. B. Pre-Shared Keys) konkreten <code>CryptoKeySlot</code>-Ressourcen zu.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComCertificateToCryptoCertificateMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindet Kommunikationsendpunkte des Communication Management (<code>ara::com</code>, z. B. TLS-Verbindungen bei SOME/IP oder DDS) an im Cryptography Cluster (<code>ara::crypto</code>) verwaltete X.509-Zertifikate (<code>CryptoCertificate</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FunctionalClusterToSecurityEventDefinitionMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verknüpft funktionale Cluster mit Security-Event-Definitionen (<code>SecurityEventDefinition</code>) des Intrusion Detection System Manager (IdsM), um sicherheitsrelevante Ereignisse und Anomalien standardisiert an das IdsM zu melden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert eine rein statische Metamodell-Struktur für Build- und Packaging-Artefakte (Manifeste). Die zur Laufzeit abgeleitete Dynamik gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Manifest-Evaluation & Deployment (UCM / Execution Management):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beim Parsen des Manifest-Pakets liest der Plattform-Bootstrapper die Subklassen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> ein.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inter-Cluster-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Persistency & Crypto:</em> <code>ara::per</code> fragt beim Start über den Crypto-Provider den im Mapping definierten <code>CryptoKeySlot</code> ab. Stimmen <code>keySlotUsage</code> oder <code>verificationHash</code> nicht mit den Crypto-Manifest-Definitionen überein, schlägt die Initialisierung der Storage-Instanz fehl.</li>\n<li><em>Communication & SecOC / Crypto:</em> Der Netzwerk-Stack verifiziert vor dem Senden/Empfangen gesicherter PDUs die Verfügbarkeit der zugeordneten Slots und Zertifikate.</li>\n<li><em>TimeSync & Persistency:</em> <code>ara::tsync</code> liest synchron gespeicherte Zeitversatzdaten aus dem gemappten Persistenzspeicher ein, bevor die Zeitbasis als synchronisiert (<code>kSynchronized</code>) an Clients gemeldet wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerpfade:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ungültige oder unauflösbare Referenzen führen zu Plattform-Initialisierungsfehlern, die über das Platform Health Management (PHM) erfasst oder via DLT als kritischer Fehler geloggt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>TPS_MANI_03268</code>):</strong></li>\n<li>Schreibt vor, dass sämtliche plattforminternen Cluster-Interaktionen und Querverweise explizit über die Spezialisierungen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> deklariert werden müssen. Versteckte, herstellerspezifische Abhängigkeiten zwischen funktionalen Clustern verletzen die Konformität.</li>\n<li><strong>Konfigurations- & Integrator-Pflichten:</strong></li>\n<li><em>Ressourcen-Isolation:</em> Integratoren müssen für jedes Persistenz- und Kommunikations-Deployment eindeutige Key-Slot- und Kanal-Mappings definieren. Schlüsselkollisionen werden durch <code>verificationHash</code> frühzeitig zur Konfigurations-Validierungszeit abgefangen.</li>\n<li><em>Granularität:</em> Entwickler müssen zwischen Storage-weiter Verschlüsselung (<code>PersistencyDeploymentToCryptoKeySlotMapping</code>) und datei-/schlüsselspezifischer Verschlüsselung (<code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>) differenzieren, um Overheads im Crypto-Hardwaretreiber (z. B. HSM/SE) zu minimieren.</li>\n<li><strong>Implementierungs-Vertrag für Stack-Anbieter:</strong></li>\n<li>Codegeneratoren für <code>ara::per</code>, <code>ara::com</code> und <code>ara::tsync</code> müssen diese Mappings auswerten, um die entsprechenden Driver-Handles, IPC-Endpunkte und Proxy/Skeleton-Instanzen konsistent aufeinander abzustimmen.</li>\n<li>Applikations-SWCs interagieren ausschließlich mit den abstrakten Standard-APIs (z. B. <code>ara::per::OpenFileStorage</code>); das Routing zu HSM-Slots oder DLT-Kanälen erfolgt für die Anwendung vollkommen transparent auf Basis dieser Mappings.</li>\n</ul>"}, {"id": "FIG-f91140170c62240b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Adaptive Platform Manifests / ARXML-Metamodell).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R20-11, Dokumentation <code>AUTOSAR_TPS_ManifestSpecification</code>, Kapitel 12 (<em>Interaction between Functional Clusters</em>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Modellierung und Entkopplung von hersteller- und clusterspezifischen Querverbindungen sowie Ressourcen-Abhängigkeiten zwischen standardisierten Functional Clustern (FCs) der Adaptive Platform Foundation/Services. Anstelle proprietärer IPC-Mechanismen oder hardkodierter Pfade ermöglicht die Spezialisierungshierarchie die deklarative Zuordnung von kryptografischen Schlüsselslots, Zertifikaten, Persistenzbereichen, Zeitbasen und Diagnose-Log-Kanälen im Machine- bzw. Platform-Manifest.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Abstrakte Basisebene</p>\n<ul class=\"fig-list\">\n<li><strong><code>UploadableDeploymentElement</code>:</strong></li>\n<li>Abstrakte Metaklasse des ARXML-Metamodells, die festlegt, dass Instanzen als deployment-spezifische Konfigurationselemente eigenständig über Update and Configuration Management (UCM) deployt werden können.</li>\n<li><strong><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> (kursiv/abstrakt):</strong></li>\n<li>Generalisierung aller Interaktions-Mappings zwischen zwei oder mehr Functional Clustern. Spezialisiert <code>UploadableDeploymentElement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierte Subklassen (Konkrete Mapping-Entitäten)</p>\n<ol class=\"fig-list\">\n<li><strong><code>FunctionalClusterToDltLogSinkMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verknüpft einen beliebigen funktionalen Cluster mit einer DLT-Log-Senke (<code>DltLogSink</code>), um Cluster-spezifische Log- und Trace-Meldungen direkt an definierte Protokollsenken des DLT-Clusters zu routen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ArtifactChecksumToCryptoProviderMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt Prüfsummen von Software-Artefakten auf kryptografische Provider (<code>CryptoProvider</code>), um kryptografische Integritäts- und Authentizitätsprüfungen von Artefakten durchzuführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt ein globales Persistenz-Deployment (<code>PersistencyDeployment</code>, z. B. <code>PersistencyFileStorage</code> oder <code>PersistencyKeyValueStorage</code>) auf einen kryptografischen Schlüsselslot (<code>CryptoKeySlot</code>).</li>\n<li>Attribute:</li>\n<li><code>+ cryptoAlgorithmString: String [0..1]</code>: Spezifiziert den für die Persistenzverschlüsselung zu verwendenden kryptografischen Algorithmus als String-Identifier.</li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code>: Spezifiziert den Einsatzzweck des Schlüsselslots innerhalb der Persistenz (z. B. Verschlüsselung von Datenblöcken oder Integritätssicherung).</li>\n<li><code>+ verificationHash: String [0..1]</code>: Optionaler kryptografischer Hashwert zur Integritäts- und Konsistenzprüfung des referenzierten Schlüsselinhalts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Zuordnung auf Elementebene: Mappt einzelne Dateien oder einzelne Key-Value-Einträge (<code>PersistencyDeploymentElement</code>) auf dedizierte <code>CryptoKeySlot</code>-Instanzen.</li>\n<li>Attribute:</li>\n<li><code>+ cryptoAlgorithmString: String [0..1]</code></li>\n<li><code>+ keySlotUsage: CryptoKeySlotUsageEnum [0..1]</code></li>\n<li><code>+ verificationHash: String [0..1]</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>PersistencyDeploymentToDltLogSinkMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weist einem <code>PersistencyDeployment</code> dedizierte Log-Senken (<code>DltLogSink</code>) des Diagnostic Log and Trace Clusters (<code>ara::dlt</code>) zu, um Persistenz-Events, I/O-Fehler und Protokollmeldungen an konfigurierte Protokollsenken weiterzuleiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>TimeBaseProviderToPersistencyMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mappt den Zeitbasen-Provider des Time Synchronization Clusters (<code>TimeBaseProvider</code> / <code>ara::tsync</code>) auf eine Persistenz-Ressource (<code>ara::per</code>), um Zeitkorrekturwerte, Offset-Werte und Drift-Zustände über Reboot- und Power-Down-Zyklen hinweg zu konservieren.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComSecOcToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verbindet die PDU-Authentifizierung und Freshness-Prüfung von Secure Onboard Communication (<code>SecOC</code>) mit den kryptografischen Schlüsselslots zur MAC-Generierung und -Verifikation.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComKeyToCryptoKeySlotMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ordnet Kommunikationsprotokoll-Sicherheitsschlüssel (z. B. Pre-Shared Keys) konkreten <code>CryptoKeySlot</code>-Ressourcen zu.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>ComCertificateToCryptoCertificateMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bindet Kommunikationsendpunkte des Communication Management (<code>ara::com</code>, z. B. TLS-Verbindungen bei SOME/IP oder DDS) an im Cryptography Cluster (<code>ara::crypto</code>) verwaltete X.509-Zertifikate (<code>CryptoCertificate</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>FunctionalClusterToSecurityEventDefinitionMapping</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verknüpft funktionale Cluster mit Security-Event-Definitionen (<code>SecurityEventDefinition</code>) des Intrusion Detection System Manager (IdsM), um sicherheitsrelevante Ereignisse und Anomalien standardisiert an das IdsM zu melden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert eine rein statische Metamodell-Struktur für Build- und Packaging-Artefakte (Manifeste). Die zur Laufzeit abgeleitete Dynamik gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Manifest-Evaluation & Deployment (UCM / Execution Management):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Beim Parsen des Manifest-Pakets liest der Plattform-Bootstrapper die Subklassen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> ein.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Inter-Cluster-Bindung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Persistency & Crypto:</em> <code>ara::per</code> fragt beim Start über den Crypto-Provider den im Mapping definierten <code>CryptoKeySlot</code> ab. Stimmen <code>keySlotUsage</code> oder <code>verificationHash</code> nicht mit den Crypto-Manifest-Definitionen überein, schlägt die Initialisierung der Storage-Instanz fehl.</li>\n<li><em>Communication & SecOC / Crypto:</em> Der Netzwerk-Stack verifiziert vor dem Senden/Empfangen gesicherter PDUs die Verfügbarkeit der zugeordneten Slots und Zertifikate.</li>\n<li><em>TimeSync & Persistency:</em> <code>ara::tsync</code> liest synchron gespeicherte Zeitversatzdaten aus dem gemappten Persistenzspeicher ein, bevor die Zeitbasis als synchronisiert (<code>kSynchronized</code>) an Clients gemeldet wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerpfade:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ungültige oder unauflösbare Referenzen führen zu Plattform-Initialisierungsfehlern, die über das Platform Health Management (PHM) erfasst oder via DLT als kritischer Fehler geloggt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung (<code>TPS_MANI_03268</code>):</strong></li>\n<li>Schreibt vor, dass sämtliche plattforminternen Cluster-Interaktionen und Querverweise explizit über die Spezialisierungen von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> deklariert werden müssen. Versteckte, herstellerspezifische Abhängigkeiten zwischen funktionalen Clustern verletzen die Konformität.</li>\n<li><strong>Konfigurations- & Integrator-Pflichten:</strong></li>\n<li><em>Ressourcen-Isolation:</em> Integratoren müssen für jedes Persistenz- und Kommunikations-Deployment eindeutige Key-Slot- und Kanal-Mappings definieren. Schlüsselkollisionen werden durch <code>verificationHash</code> frühzeitig zur Konfigurations-Validierungszeit abgefangen.</li>\n<li><em>Granularität:</em> Entwickler müssen zwischen Storage-weiter Verschlüsselung (<code>PersistencyDeploymentToCryptoKeySlotMapping</code>) und datei-/schlüsselspezifischer Verschlüsselung (<code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>) differenzieren, um Overheads im Crypto-Hardwaretreiber (z. B. HSM/SE) zu minimieren.</li>\n<li><strong>Implementierungs-Vertrag für Stack-Anbieter:</strong></li>\n<li>Codegeneratoren für <code>ara::per</code>, <code>ara::com</code> und <code>ara::tsync</code> müssen diese Mappings auswerten, um die entsprechenden Driver-Handles, IPC-Endpunkte und Proxy/Skeleton-Instanzen konsistent aufeinander abzustimmen.</li>\n<li>Applikations-SWCs interagieren ausschließlich mit den abstrakten Standard-APIs (z. B. <code>ara::per::OpenFileStorage</code>); das Routing zu HSM-Slots oder DLT-Kanälen erfolgt für die Anwendung vollkommen transparent auf Basis dieser Mappings.</li>\n</ul>"}], "trans": [{"from": "FIG-bf20e9aa2cbf8ad3", "to": "FIG-d3953a207d128541", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ArtifactChecksumToCryptoProviderMapping</code>: Neue Mapping-Klasse als Spezialisierung von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> hinzugefügt.</li>\n<li><code>PersistencyDeploymentToDltLogSinkMapping</code>: Ersetzt die bisherige Metaklasse <code>PersistencyDeploymentToDltLogChannelMapping</code>.</li>\n<li>Diagrammlayout: Von einzeilig horizontaler Auffächerung auf zweispaltige Anordnung der Subklassen umgestellt.</li>\n</ul>"}, {"from": "FIG-d3953a207d128541", "to": "FIG-503f067b90ed1904", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PersistencyDeploymentToCryptoKeySlotMapping</code>: Neues Attribut <code>+ cryptoAlgorithmString: String [0..1]</code> ergänzt.</li>\n<li><code>PersistencyDeploymentElementToCryptoKeySlotMapping</code>: Neues Attribut <code>+ cryptoAlgorithmString: String [0..1]</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-503f067b90ed1904", "to": "FIG-2dc21ccbfe84f651", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>: Basisklasse von <code>UploadablePackageElement</code> auf <code>UploadableDeploymentElement</code> geändert.</li>\n<li><code>FunctionalClusterToSecurityEventDefinitionMapping</code>: Neue Mapping-Klasse als Spezialisierung von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-2dc21ccbfe84f651", "to": "FIG-85181755e287e540", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-85181755e287e540", "to": "FIG-f91140170c62240b", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>FunctionalClusterToDltLogSinkMapping</code>: Neue Mapping-Klasse als Spezialisierung von <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> hinzugefügt.</li>\n</ul>"}]};
